import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.C2TvIV46.js";const m=JSON.parse('{"title":"Math operations","description":"","frontmatter":{},"headers":[],"relativePath":"language/enums/math-operations.md","filePath":"language/enums/math-operations.md"}'),s={name:"language/enums/math-operations.md"};function c(r,e,n,l,i,p){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="math-operations" tabindex="-1">Math operations <a class="header-anchor" href="#math-operations" aria-label="Permalink to &quot;Math operations&quot;">​</a></h1><p>Operators for actions that modify a numeric value in place. Operand order is always <code>&lt;target&gt; &lt;operation&gt; &lt;value&gt;</code> (for example <code>action set my_counter add 1</code>).</p><p>Used by <a href="/MegaloEvolved/beta/docs/language/actions/set"><code>set</code></a>, <a href="/MegaloEvolved/beta/docs/language/actions/set-score"><code>set_score</code></a>, <a href="/MegaloEvolved/beta/docs/language/actions/player-adjust-money"><code>player_adjust_money</code></a>, <a href="/MegaloEvolved/beta/docs/language/actions/adjust-grenades"><code>adjust_grenades</code></a>, and the <a href="/MegaloEvolved/beta/docs/language/actions/object-adjust-health"><code>object_adjust_*</code></a> health/shield actions.</p><p>Values match <code>e_math_operation</code> in <a href="https://github.com/Blam-Network/blf/blob/main/blf-ts/src/blam/haloreach_mcc/v_untracked_25_08_16_1352/game/megalogamengine/megalogamengine_actions.ts" target="_blank" rel="noreferrer">@blamnetwork/blf</a>. Reach scripts spell operators as words (<code>add</code>, <code>set_to</code>, <code>multiply</code>); the decompiler emits assignment-style symbols (<code>+=</code>, <code>=</code>, <code>*=</code>). Both forms are accepted.</p><table tabindex="0"><thead><tr><th>Operator</th><th>Symbol</th><th>Effect</th><th>Added in</th></tr></thead><tbody><tr><td><code>add</code></td><td><code>+=</code></td><td>Add to the current value</td><td><a href="/MegaloEvolved/beta/docs/versions/49/">49</a></td></tr><tr><td><code>subtract</code></td><td><code>-=</code></td><td>Subtract from the current value</td><td><a href="/MegaloEvolved/beta/docs/versions/49/">49</a></td></tr><tr><td><code>multiply</code></td><td><code>*=</code></td><td>Multiply the current value</td><td><a href="/MegaloEvolved/beta/docs/versions/49/">49</a></td></tr><tr><td><code>divide</code></td><td><code>/=</code></td><td>Divide the current value</td><td><a href="/MegaloEvolved/beta/docs/versions/49/">49</a></td></tr><tr><td><code>set_to</code></td><td><code>=</code></td><td>Assign (replace) the current value</td><td><a href="/MegaloEvolved/beta/docs/versions/49/">49</a></td></tr><tr><td><code>modulo</code></td><td><code>%=</code></td><td>Replace with the remainder after division</td><td><a href="/MegaloEvolved/beta/docs/versions/49/">49</a></td></tr><tr><td><code>and</code></td><td><code>&amp;=</code></td><td>Bitwise AND with the operand</td><td><a href="/MegaloEvolved/beta/docs/versions/49/">49</a></td></tr><tr><td><code>or</code></td><td><code>|=</code></td><td>Bitwise OR with the operand</td><td><a href="/MegaloEvolved/beta/docs/versions/49/">49</a></td></tr><tr><td><code>xor</code></td><td><code>^=</code></td><td>Bitwise XOR with the operand</td><td><a href="/MegaloEvolved/beta/docs/versions/73/">73</a></td></tr><tr><td><code>not</code></td><td><code>~=</code></td><td>Bitwise NOT merge (<code>a not b</code> → <code>a &amp;= ~b</code>)</td><td><a href="/MegaloEvolved/beta/docs/versions/73/">73</a></td></tr><tr><td><code>abs</code></td><td>—</td><td>Set to the absolute value of the operand</td><td><a href="/MegaloEvolved/beta/docs/versions/73/">73</a></td></tr><tr><td><code>lshift</code></td><td><code>&lt;&lt;</code></td><td>Bit-shift left and assign</td><td><a href="/MegaloEvolved/beta/docs/versions/107-mcc/">107 (MCC)</a></td></tr><tr><td><code>rshift</code></td><td><code>&gt;&gt;</code></td><td>Bit-shift right and assign</td><td><a href="/MegaloEvolved/beta/docs/versions/107-mcc/">107 (MCC)</a></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>Omaha Alpha (build <strong>49</strong>) stores the operation in three bits, so only the first eight operators above are encodable. Omaha Delta (<strong>73</strong>) widens the field to four bits and adds XOR, NOT, and absolute assignment. Reach MCC (<strong>107 MCC</strong>) adds the bit-shift operators; on MCC builds <code>abs</code> is enum index <strong>12</strong> (it is index <strong>10</strong> on Xbox 360 TU1).</p><p>@blamnetwork/megalo accepts word names and symbols. Legacy blf enum names (<code>multiply_by</code>, <code>set_to_absolute</code>, …) are still accepted when parsing older scripts.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action set my_counter set_to </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-text">action set my_counter add </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-text">action set temp modulo </span><span class="megalo-number">5</span></span>
<span class="line"><span class="megalo-text">action set_score add kill_points player killing_player</span></span>
<span class="line"><span class="megalo-text">action object_adjust_shield current_player set_to </span><span class="megalo-number">100</span></span></code></pre></div>`,10)])])}const g=t(s,[["render",c]]);export{m as __pageData,g as default};
